1497	/// Capture's one OCR call (`media-ocr`) — posts via the shared
1498	/// `ApiClient`, mirroring `entries_remote_data_source.dart`'s pattern.
1499	/// Base64-encodes the image bytes here, and only here (Boundaries) — no
1500	/// other layer ever handles the raw bytes in that encoded form.
1501	class MediaRemoteDataSource {
1502	  MediaRemoteDataSource(this._apiClient);
1503	
1504	  final ApiClient _apiClient;
1505	
1506	  Future<Either<Failure, OcrResult>> recognizeText({
1507	    required Uint8List imageBytes,
1508	    required String mimeType,
1509	  }) async {
1510	    final result = await _apiClient.post(
1511	      'media-ocr',
1512	      data: {'image': base64Encode(imageBytes), 'mimeType': mimeType},
1513	    );
1514	    return result.flatMap((json) {
1515	      try {
1516	        final data = json['data'] as Map<String, dynamic>;
1517	        return right(
1518	          OcrResult(
1519	            text: data['text'] as String,
1520	            confidence: data['confidence'] as String,
1521	          ),
1522	        );
1523	      } catch (error) {
1524	        // A 200 response that doesn't match the expected shape is a
1525	        // client-side parse failure, never a backend-sent code — maps to
1526	        // the local-only `malformedResponse` (RNF09: no exception escapes
1527	        // unmapped).
1528	        return left(Failure.malformedResponse(message: error.toString()));
1529	      }
1530	    });
1531	  }
1532	}
